Span<nint> values = stackalloc nint[] { 1, 2, 3, 4, 5 };

Console.WriteLine($"Length: {values.Length}");
Console.WriteLine($"Element size: {sizeof(nint)} bytes");

nint sum = 0;
for (int i = 0; i < values.Length; i++)
{
    sum += values[i];
    Console.WriteLine($"  values[{i}] = {values[i]}");
}
Console.WriteLine($"Sum: {sum}");

// Also test with a fixed size (not collection expression)
Span<nint> fixed4 = stackalloc nint[4];
fixed4[0] = nint.MaxValue;
Console.WriteLine($"\nnint.MaxValue = {fixed4[0]}");
Console.WriteLine($"Environment.Is64BitProcess = {Environment.Is64BitProcess}");

